<?php
namespace App\Http\Controllers;use App\Models\RhPeriodePaie;use App\Services\{CurrentEntreprise,RhWorkflowService};use Illuminate\Http\Request;
class RhPeriodePaieController extends Controller{public function index(CurrentEntreprise $c){$id=$c->for()->id;return view('ressources_humaines.periodes.index',['periodes'=>RhPeriodePaie::where('entreprise_id',$id)->latest('date_debut')->paginate(20)]);}public function store(Request $r,CurrentEntreprise $c){$d=$r->validate(['libelle'=>'required|string|max:100','date_debut'=>'required|date','date_fin'=>'required|date|after_or_equal:date_debut','annee'=>'required|integer|min:2000|max:2100','mois'=>'required|integer|min:1|max:12']);RhPeriodePaie::create($d+['entreprise_id'=>$c->for()->id,'cree_par'=>$r->user()->id,'statut'=>'Ouverte']);return back()->with('success','Période de paie ouverte.');}public function transition(Request $r,RhPeriodePaie $periode,RhWorkflowService $w,CurrentEntreprise $c){abort_unless($periode->entreprise_id===$c->for()->id,404);$d=$r->validate(['statut'=>'required|in:En préparation,Calculée,Validée,Payée,Clôturée']);$w->transition($periode,$d['statut'],['Ouverte'=>['En préparation'],'En préparation'=>['Calculée'],'Calculée'=>['Validée'],'Validée'=>['Payée'],'Payée'=>['Clôturée']],$r->user()->id);return back()->with('success','Période mise à jour.');}}
